import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Hardware test checklist","description":"","frontmatter":{},"headers":[],"relativePath":"test-checklist.md","filePath":"test-checklist.md","lastUpdated":1793129134000}'),n={name:"test-checklist.md"};function o(r,e,l,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="hardware-test-checklist" tabindex="-1">Hardware test checklist <a class="header-anchor" href="#hardware-test-checklist" aria-label="Permalink to &quot;Hardware test checklist&quot;">​</a></h1><p>This page lists the checks that can only be done on a real Windows computer: audio, shortcuts, the panel, speech synthesis and real provider latency. Automated tests cover the rest. Run through it before each release, after installing with <code>scoop install meetcue</code>.</p><p>When an item fails, note the error code if any, <a href="/meetcue/troubleshooting/diagnostics">export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="self-test-first" tabindex="-1">Self-test first <a class="header-anchor" href="#self-test-first" aria-label="Permalink to &quot;Self-test first&quot;">​</a></h2><ul><li>[ ] <code>MeetCue.exe --version</code> prints the expected version.</li><li>[ ] <code>MeetCue.exe --self-test</code>, with speakers muted or headphones on, reports all items as passed.</li></ul><h2 id="setup-and-demo" tabindex="-1">Setup and demo <a class="header-anchor" href="#setup-and-demo" aria-label="Permalink to &quot;Setup and demo&quot;">​</a></h2><ul><li>[ ] The first start opens the setup window. After entering speech and model keys, the latency probe shows a result table and a ranked list of combinations.</li><li>[ ] <code>MeetCue.exe --demo</code> plays the whole sample interview.</li></ul><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><ul><li>[ ] Playing a video makes the system sound level move; speaking makes the microphone level move.</li><li>[ ] With speakers instead of headphones, the other side&#39;s words are not attributed to you.</li><li>[ ] Unplugging headphones or switching the default device restores capture automatically.</li></ul><h2 id="meeting" tabindex="-1">Meeting <a class="header-anchor" href="#meeting" aria-label="Permalink to &quot;Meeting&quot;">​</a></h2><ul><li>[ ] In a real meeting, a question block with talking points appears about 1.5 seconds after the other person finishes a question, and the footer latency matches.</li><li>[ ] While answering, points you cover are ticked and the next one is highlighted.</li><li>[ ] A question asked while you answer goes to <strong>Next</strong> without replacing the current hints.</li><li>[ ] All nine shortcuts work, holding a move shortcut glides the panel and stops on release, and the meeting app&#39;s own shortcuts (such as <code>Ctrl+Shift+M</code> in Teams) still work.</li><li>[ ] Clicking the panel doesn&#39;t take focus from the meeting window.</li><li>[ ] When sharing the whole screen, the other side can&#39;t see the panel.</li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ul><li>[ ] <strong>Mock interview…</strong> in the tray menu, <strong>Try a mock interview</strong> on the idle panel, <strong>Settings › General › Open mock interview</strong> and <strong>Finish and try a mock interview</strong> in setup all open the mock interview window.</li><li>[ ] In the sound check step, both level bars move, each language&#39;s voice list is filled, and <strong>Try it</strong> speaks a sample in the chosen voice.</li><li>[ ] <strong>Ask again</strong> reads the current question from the start, in the practice window and on the panel.</li><li>[ ] A cough or an &quot;um&quot; while a question is read doesn&#39;t cut it short; answering properly does.</li><li>[ ] Each built-in sample loads with <strong>Use this</strong>; follow the <a href="/meetcue/guide/mock-interview#self-test-plan">self-test plan</a> for at least rounds 1 and 3.</li><li>[ ] Practice one round each with the sample subtitles and the sample question list.</li><li>[ ] Hints appear with <strong>Speech-to-text for the questions</strong> both on and off.</li><li>[ ] Switching between the four hint levels works.</li><li>[ ] The review report can be exported.</li></ul><h2 id="languages-and-errors" tabindex="-1">Languages and errors <a class="header-anchor" href="#languages-and-errors" aria-label="Permalink to &quot;Languages and errors&quot;">​</a></h2><ul><li>[ ] Switching between English and Simplified Chinese in the settings changes the panel, tray menu, error messages and practice report immediately.</li><li>[ ] A deliberately wrong key shows an error code; <strong>See the fix</strong> opens the documentation in the current language at that error code.</li><li>[ ] The diagnostics zip contains no API keys.</li></ul><h2 id="updates-and-documentation" tabindex="-1">Updates and documentation <a class="header-anchor" href="#updates-and-documentation" aria-label="Permalink to &quot;Updates and documentation&quot;">​</a></h2><ul><li>[ ] After <code>scoop update meetcue</code>, settings, keys, latency history and practice records are still there.</li><li>[ ] The documentation site reads well on a phone and a computer; switching language keeps you on the same page; searching for a Chinese term finds results.</li></ul>',17)])])}const g=t(n,[["render",o]]);export{p as __pageData,g as default};
